var keys={},drag=false,lastX=0,lastY=0,yaw=0,pitch=0,hud;
function reset(){camera.position.set(255,135,330);camera.lookAt(0,65,-35);var e=new THREE.Euler().setFromQuaternion(camera.quaternion,'YXZ');yaw=e.y;pitch=e.x;}
function down(e){keys[e.code]=true;if(['ArrowUp','ArrowDown','ArrowLeft','ArrowRight','Space'].includes(e.code))e.preventDefault();if(e.code==='KeyR')reset();}
function up(e){keys[e.code]=false;}
function pd(e){drag=true;lastX=e.clientX;lastY=e.clientY;}
function pu(){drag=false;}
function pm(e){if(!drag)return;yaw-=(e.clientX-lastX)*.004;pitch=Math.max(-1.4,Math.min(1.4,pitch-(e.clientY-lastY)*.004));lastX=e.clientX;lastY=e.clientY;camera.quaternion.setFromEuler(new THREE.Euler(pitch,yaw,0,'YXZ'));}
function wheel(e){camera.translateZ(Math.sign(e.deltaY)*3);e.preventDefault();}
function blur(){keys={};drag=false;}
function start(){reset();renderer.domElement.style.touchAction='none';window.addEventListener('keydown',down);window.addEventListener('keyup',up);window.addEventListener('pointermove',pm);window.addEventListener('pointerup',pu);window.addEventListener('blur',blur);renderer.domElement.addEventListener('pointerdown',pd);renderer.domElement.addEventListener('wheel',wheel,{passive:false});}
function update(event){var dt=Math.min(event.delta/1000,.05),v=dt*(keys.ShiftLeft||keys.ShiftRight?65:20);var forward=(keys.KeyW||keys.ArrowUp?1:0)-(keys.KeyS||keys.ArrowDown?1:0),side=(keys.KeyD||keys.ArrowRight?1:0)-(keys.KeyA||keys.ArrowLeft?1:0);var norm=Math.max(1,Math.hypot(forward,side));camera.translateZ(-forward*v/norm);camera.translateX(side*v/norm);camera.position.y+=((keys.KeyE?1:0)-(keys.KeyQ?1:0))*v;camera.position.y=Math.max(4,Math.min(450,camera.position.y));camera.position.x=Math.max(-650,Math.min(650,camera.position.x));camera.position.z=Math.max(-500,Math.min(650,camera.position.z));}
function stop(){window.removeEventListener('keydown',down);window.removeEventListener('keyup',up);window.removeEventListener('pointermove',pm);window.removeEventListener('pointerup',pu);window.removeEventListener('blur',blur);renderer.domElement.removeEventListener('pointerdown',pd);renderer.domElement.removeEventListener('wheel',wheel);if(hud)hud.remove();keys={};}
